import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';

// This script deliberately sends hostile requests. Use a disposable test project.
// No admin key is accepted, and cleanup only targets IDs generated by this run.
async function main() {
  const env = process.env;
  if (env.ISOLATION_TEST_ALLOW_WRITES !== 'yes') {
    throw new Error('Not run: set ISOLATION_TEST_ALLOW_WRITES=yes for a disposable test project.');
  }
  const required = [
    'EXPO_PUBLIC_SUPABASE_URL', 'EXPO_PUBLIC_SUPABASE_PUBLISHABLE_KEY',
    'ISOLATION_TEST_EMAIL_A', 'ISOLATION_TEST_PASSWORD_A',
    'ISOLATION_TEST_EMAIL_B', 'ISOLATION_TEST_PASSWORD_B',
  ];
  for (const name of required) if (!env[name]) throw new Error(`Missing ${name}.`);
  assert.ok(env.EXPO_PUBLIC_SUPABASE_PUBLISHABLE_KEY.startsWith('sb_publishable_'),
    'Use a publishable key; admin/secret and legacy keys are not accepted by this test.');
  assert.notEqual(env.ISOLATION_TEST_EMAIL_A.toLowerCase(), env.ISOLATION_TEST_EMAIL_B.toLowerCase(),
    'Two different disposable accounts are required.');

  const { createClient } = await import('@supabase/supabase-js');
  const client = () => createClient(env.EXPO_PUBLIC_SUPABASE_URL,
    env.EXPO_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
    {auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}});
  const a=client(), b=client(), anonymous=client();
  const run=`isolation-${randomUUID()}`;
  const ids=[`${run}-a`,`${run}-b`,`${run}-spoof`,`${run}-anon`];
  let ownerA, ownerB;
  function payload(id, title='Isolation test') {
    return {id,title,notes:'Disposable test record',createdAt:new Date().toISOString(),stops:[]};
  }
  function ok(result,label) { assert.equal(result.error,null,`${label} failed (${result.error?.code??'unknown'}).`); return result.data; }
  async function readAs(c,id) { return ok(await c.from('trips').select('id,user_id,payload').eq('id',id),'Read'); }
  async function noRows(request,label) {
    const result=await request;
    if(result.error) {
      assert.equal(result.error.code,'42501',`${label}: unexpected error; isolation not verified.`);
    } else assert.deepEqual(result.data,[],`${label}: accessed another account's data.`);
  }
  async function denied(request,label) {
    const result=await request;
    assert.equal(result.error?.code,'42501',`${label}: expected an authorization rejection.`);
  }
  try {
    const loginA=ok(await a.auth.signInWithPassword({email:env.ISOLATION_TEST_EMAIL_A,password:env.ISOLATION_TEST_PASSWORD_A}),'Account A login');
    const loginB=ok(await b.auth.signInWithPassword({email:env.ISOLATION_TEST_EMAIL_B,password:env.ISOLATION_TEST_PASSWORD_B}),'Account B login');
    ownerA=loginA.user.id; ownerB=loginB.user.id;
    assert.notEqual(ownerA,ownerB,'Test sessions must belong to different users.');
    ok(await a.from('trips').insert({id:ids[0],user_id:ownerA,payload:payload(ids[0])}),'A inserts own trip');
    ok(await b.from('trips').insert({id:ids[1],user_id:ownerB,payload:payload(ids[1])}),'B inserts own trip');
    assert.equal((await readAs(a,ids[0])).length,1,'A must see own trip.');
    assert.equal((await readAs(b,ids[1])).length,1,'B must see own trip.');

    await noRows(b.from('trips').select('*').eq('id',ids[0]),'B reads A by known ID');
    await noRows(a.from('trips').select('*').eq('id',ids[1]),'A reads B by known ID');
    await noRows(b.from('trips').select('*').eq('user_id',ownerA),'B spoofs an owner filter');
    await noRows(anonymous.from('trips').select('*').in('id',ids),'Anonymous reads');
    const bulk=ok(await b.from('trips').select('id,user_id'),'B bulk read');
    assert.ok(bulk.every(row=>row.user_id===ownerB),'Unfiltered query leaked other owners.');

    await denied(b.from('trips').insert({id:ids[2],user_id:ownerA,payload:payload(ids[2])}),'B inserts as A');
    await denied(anonymous.from('trips').insert({id:ids[3],user_id:ownerA,payload:payload(ids[3])}),'Anonymous inserts');
    await noRows(b.from('trips').update({payload:payload(ids[0],'Tampered')}).eq('id',ids[0]).select('id'),'B edits A');
    await noRows(b.from('trips').delete().eq('id',ids[0]).select('id'),'B deletes A');
    await denied(b.from('trips').upsert({id:ids[0],user_id:ownerB,payload:payload(ids[0],'Stolen')}),'B steals A through upsert');
    await denied(b.from('trips').update({user_id:ownerA}).eq('id',ids[1]),'B transfers ownership');
    const intactA=await readAs(a,ids[0]);
    assert.equal(intactA.length,1,'Cross-account request removed A record.');
    assert.equal(intactA[0].payload.title,'Isolation test','Cross-account request changed A record.');
    assert.equal(intactA[0].user_id,ownerA,'Cross-account request changed A owner.');
    assert.equal((await readAs(b,ids[1]))[0].user_id,ownerB,'B record ownership changed.');
    ok(await a.from('trips').update({payload:payload(ids[0],'Owner edit')}).eq('id',ids[0]),'Owner edits');
    assert.equal((await readAs(a,ids[0]))[0].payload.title,'Owner edit','Owner update did not apply.');
    ok(await a.from('trips').delete().eq('id',ids[0]),'Owner deletes');
    assert.equal((await readAs(a,ids[0])).length,0,'Owner delete did not apply.');
    console.log('PASS: owner access and cross-account/anonymous isolation checks.');
  } finally {
    // Even after a failed security assertion, clean only this run's test records.
    let cleanupFailed=false;
    for(const [c,owner] of [[a,ownerA],[b,ownerB]]) if(owner) {
      const result=await c.from('trips').delete().in('id',ids).eq('user_id',owner);
      if(result.error)cleanupFailed=true;
      else {
        const verify=await c.from('trips').select('id').in('id',ids).eq('user_id',owner);
        if(verify.error||verify.data.length)cleanupFailed=true;
      }
    }
    if(cleanupFailed) {
      console.error(`Cleanup incomplete. Inspect only test trip IDs beginning ${run}.`);
      process.exitCode=1;
    }
  }
}
main().catch(error=>{console.error(error.message);process.exitCode=1;});
